import { readFileSync } from 'node:fs'
import { Client, Wallet } from 'xrpl'
import { InMemoryBanRegistry, MptIssuer, transfer, TransactionFailedError } from './src/index.js'

const st = JSON.parse(readFileSync('.demo-holders.json', 'utf8'))
const id: string = st.issuanceId
const A = Wallet.fromSeed(st.holders.A.seed)
const B = Wallet.fromSeed(st.holders.B.seed)
const C = Wallet.fromSeed(st.holders.C.seed)
const I = Wallet.fromSeed(process.env.ISSUER_SEED!)
const client = new Client('wss://s.altnet.rippletest.net:51233')
await client.connect()
const iss = await MptIssuer.open({ client, issuerWallet: I, issuanceId: id, banRegistry: new InMemoryBanRegistry() })
async function t(label: string, fn: () => Promise<unknown>) {
  try { await fn(); console.log(label, 'SUCCESS') } catch (e) { console.log(label, e instanceof TransactionFailedError ? e.resultCode : String(e)) }
}
const bal = async () => console.log('  A', (await iss.getHolderState(A.classicAddress)), '\n  B', (await iss.getHolderState(B.classicAddress)).balance)
await bal()
// A is frozen now
await t('frozen A -> issuer 10', () => transfer(client, A, I.classicAddress, id, 10n))
await t('clawback from frozen A 1', () => iss.clawback(A.classicAddress, 1n))
await iss.unfreezeHolder(A.classicAddress)
await iss.freezeAll()
await t('global: issuer -> B 1', () => transfer(client, I, B.classicAddress, id, 1n))
await t('global: B -> issuer 1', () => transfer(client, B, I.classicAddress, id, 1n))
await t('global: clawback B 1', () => iss.clawback(B.classicAddress, 1n))
await iss.unfreezeAll()
await iss.revokeHolder(C.classicAddress)
await t('unauth C -> issuer 1', () => transfer(client, C, I.classicAddress, id, 1n))
await t('unauth C -> A 1', () => transfer(client, C, A.classicAddress, id, 1n))
await t('clawback unauth C 1', () => iss.clawback(C.classicAddress, 1n))
await bal()
await client.disconnect()

